import { BrandAvatarItem } from 'components/BrandAvatar';
import { FlaggedImgType } from 'components/Table/types/data';

import {
  StyledFlaggedBrandCellRenderer,
  StyledFlaggedBrandCellRendererDescription,
  StyledFlaggedBrandCellRendererMainFlag,
} from './FlaggedBrandCellRenderer.styles';

interface FlaggedBrandCellRendererProps extends FlaggedImgType {
  dataTestId?: string;
}

export const FlaggedBrandCellRenderer = ({
  mainFlag,
  badgeFlag,
  description,
  mainFlagName,
  dataTestId,
}: FlaggedBrandCellRendererProps) => {
  return (
    <StyledFlaggedBrandCellRenderer data-testid={dataTestId}>
      <BrandAvatarItem
        mainBrand={mainFlag}
        badgeFlag={badgeFlag}
        title={null as unknown as string}
      />

      {mainFlagName && (
        <StyledFlaggedBrandCellRendererMainFlag>
          {mainFlagName}
        </StyledFlaggedBrandCellRendererMainFlag>
      )}
      {description && (
        <StyledFlaggedBrandCellRendererDescription>
          {description}
        </StyledFlaggedBrandCellRendererDescription>
      )}
    </StyledFlaggedBrandCellRenderer>
  );
};
